// Filter new tokens that pass the criteria
const pairs = $json.pairs || [];
const now = Date.now();

const result = [];
for (const p of pairs) {
  if (p.chainId !== 'solana') continue;

  const liq = parseFloat(p.liquidity?.usd || 0);
  const vol = parseFloat(p.volume?.h24 || 0);
  const mcap = parseFloat(p.marketCap || p.fdv || 0);
  const created = p.pairCreatedAt || 0;
  const ageHours = created ? (now - created) / 3600000 : 9999;

  // CRITERIA — edit to your preference
  const passes =
    liq >= 20000 &&          // min liquidity $20k
    vol >= 10000 &&          // min 24h volume $10k
    mcap > 0 && mcap < 2000000 &&  // mcap below $2M
    ageHours >= 24 &&         // min age 24 hours (not a fresh launch)
    ageHours <= 720;          // max age 30 days

  if (passes) {
    result.push({
      json: {
        symbol: p.baseToken?.symbol || '?',
        name: p.baseToken?.name || '?',
        mint: p.baseToken?.mint || '',
        dex: p.dexId,
        price: p.priceUsd,
        liq, vol, mcap,
        age_hours: Math.round(ageHours),
        chg_24h: p.priceChange?.h24,
        url: p.url
      }
    });
  }
}

return result;

